/// <summary>
/// Errors as the apps see them. Messages are written for people.
/// </summary>
public class CoreException: UniffiException {
    CoreException() : base() {}
    CoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Database : CoreException {
        // Members
        public string @message;

        // Constructor
        public Database(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    
    public class Network : CoreException {
        // Members
        public string @message;

        // Constructor
        public Network(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    
    public class Io : CoreException {
        // Members
        public string @message;

        // Constructor
        public Io(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    public class NotFound : CoreException {
        public NotFound() : base() {}
    }
    
    
    
    public class Invalid : CoreException {
        // Members
        public string @message;

        // Constructor
        public Invalid(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    

    
}

class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreException.Database(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new CoreException.Network(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new CoreException.Io(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new CoreException.NotFound();
            case 5:
                return new CoreException.Invalid(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Read()", value));
        }
    }

    public override int AllocationSize(CoreException value) {
        switch (value) {

            case CoreException.Database variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Network variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Io variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.NotFound variant_value:
                return 4;

            case CoreException.Invalid variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.AllocationSize()", value));
        }
    }

    public override void Write(CoreException value, BigEndianStream stream) {
        switch (value) {
            case CoreException.Database variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Network variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Io variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.NotFound variant_value:
                stream.WriteInt(4);
                break;
            case CoreException.Invalid variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Write()", value));
        }
    }
}





